import type {
  TenantTransactionConnection,
  TenantTransactionPool,
} from "@zap-pronto/core/database/tenant-transaction";

function authorizationPool(options: { resolved?: boolean; allowed?: boolean } = {}): {
  pool: TenantTransactionPool;
  queries: string[];
} {
  const queries: string[] = [];
  const connection: TenantTransactionConnection = {
    async query(sql) {
      queries.push(sql.replace(/\s+/g, " ").trim());
      if (sql.includes("resolve_oidc_principal")) {
        return options.resolved === false ? { rows: [] } : {
          rows: [{
            tenant_id: "11111111-1111-4111-8111-111111111111",
            user_id: "22222222-2222-4222-8222-222222222222",
          }],
        };
      }
      if (sql.includes("current_actor_has_permission")) {
        return { rows: [{ allowed: options.allowed !== false }] };
      }
      return { rows: [] };
    },
    release() {},
  };
  return { pool: { async connect() { return connection; } }, queries };
}

function currentUserPool(options: { assigned?: boolean; rateAllowed?: boolean } = {}): TenantTransactionPool {
  return { async connect() {
    return {
      async query(sql) {
        if (sql.includes("consume_invitation_acceptance_rate_limit")) return { rowCount: 1, rows: [{
          allowed: options.rateAllowed !== false, remaining: options.rateAllowed === false ? 0 : 4,
          retry_after_seconds: 37, reset_at: new Date(Date.now() + 37_000),
        }] };
        if (sql.includes("accept_user_invitation_oidc")) return { rowCount: 1, rows: [{ replayed: false }] };
        if (sql.includes("resolve_oidc_principal")) return { rows: [{
          tenant_id: "11111111-1111-4111-8111-111111111111",
          user_id: "22222222-2222-4222-8222-222222222222",
        }] };
        if (sql.includes("account.id AS user_id")) return { rows: [{
          user_id: "22222222-2222-4222-8222-222222222222", email: "agent@example.test",
          display_name: "Agente", tenant_id: "11111111-1111-4111-8111-111111111111",
          tenant_name: "Clínica",
        }] };
        if (sql.includes("unit.id AS unit_id")) return { rows: options.assigned === false ? [] : [{
          unit_id: "33333333-3333-4333-8333-333333333333", unit_code: "CENTRO",
          unit_name: "Centro", role: "ATTENDANT",
        }] };
        if (sql.includes("role_permission.permission_code")) return { rows: [{
          permission: "handoff.read", scope: "UNIT", unit_id: "33333333-3333-4333-8333-333333333333",
        }] };
        return { rows: [] };
      },
      release() {},
    };
  } };
}

test("health contract and OpenAPI are generated by the same schemas", async () => {
  const app = await buildApp();
  const response = await app.inject({ method: "GET", url: "/health/live" });
  assert.equal(response.statusCode, 200);
  assert.deepEqual(response.json(), { status: "ok" });
  assert.match(String(response.headers["x-correlation-id"]), /^[0-9a-f-]{36}$/);
  const document = app.swagger();
  assert.ok(document.paths?.["/health/live"]);
  assert.ok(document.paths?.["/health/ready"]);
  assert.ok(document.paths?.["/v1/me"]);
  assert.equal(document.paths?.["/health/live"]?.get?.operationId, "getHealthLive");
  const readinessUnavailable = document.paths?.["/health/ready"]?.get?.responses?.["503"] as
    { content?: Record<string, unknown> } | undefined;
  assert.ok(readinessUnavailable?.content?.["application/problem+json"]);
  assert.equal(readinessUnavailable?.content?.["application/json"], undefined);
  assert.match(JSON.stringify(document), /bearerAuth/);
  const injected = await app.inject({ method: "GET", url: "/health/live",
    headers: { "x-correlation-id": "trusted-correlation-123" } });
  assert.equal(injected.headers["x-correlation-id"], "trusted-correlation-123");
  const rejected = await app.inject({ method: "GET", url: "/health/live",
    headers: { "x-correlation-id": "invalid id with spaces" } });
  assert.notEqual(rejected.headers["x-correlation-id"], "invalid id with spaces");
  await app.close();
});

test("readiness checks the database and fails closed without exposing its error", async () => {
  const queries: string[] = [];
  let releases = 0;
  const ready = await buildApp({ pool: { async connect() { return {
    async query(sql) { queries.push(sql); return { rows: [{ "?column?": 1 }] }; },
    release() { releases += 1; },
  }; } } });
  const healthy = await ready.inject({ method: "GET", url: "/health/ready" });
  assert.equal(healthy.statusCode, 200);
  assert.deepEqual(healthy.json(), { status: "ok" });
  assert.deepEqual(queries, ["SELECT 1"]);
  assert.equal(releases, 1);
  await ready.close();

  const unavailable = await buildApp({ pool: { async connect() { throw new Error("secret database detail"); } } });
  const failed = await unavailable.inject({ method: "GET", url: "/health/ready" });
  assert.equal(failed.statusCode, 503);
  assert.equal(failed.headers["content-type"], "application/problem+json; charset=utf-8");
  assert.deepEqual(failed.json(), {
    type: "urn:zap-pronto:error:service-unavailable", title: "Service Unavailable", status: 503,
    detail: "The service is not ready", correlationId: failed.headers["x-correlation-id"],
  });
  assert.doesNotMatch(failed.body, /secret database detail/);
  await unavailable.close();
});

