test("availability canonicalizes RFC3339 instants and maps active work to a sanitized conflict",async()=>{const unitId="33333333-3333-4333-8333-333333333333",userId="22222222-2222-4222-8222-222222222222",values:unknown[][]=[];let conflict=false;const pool:TenantTransactionPool={async connect(){return{async query(sql,input){if(sql.includes("resolve_oidc_principal"))return{rows:[{tenant_id:"11111111-1111-4111-8111-111111111111",user_id:userId}]};if(sql==="BEGIN"||sql==="COMMIT"||sql==="ROLLBACK"||sql.startsWith("SET LOCAL")||sql.includes("assert_app_context_authorized")||sql.includes("current_actor_has_permission"))return{rows:sql.includes("current_actor_has_permission")?[{allowed:true}]:[]};if(sql.includes("set_actor_unit_availability")){values.push([...(input??[])]);if(conflict)throw new Error("AVAILABILITY_ACTIVE_WORK_CONFLICT");return{rows:[{unitId,userId,status:"PAUSED",maxActive:5,pauseReason:"BREAK",pausedUntil:new Date("2030-01-01T10:00:00.123Z"),activeCount:0,version:2,updatedAt:new Date("2026-08-12T20:00:00.000Z"),replayed:false}]}}return{rows:[]}},release(){}}}};const app=await buildApp({pool,identityVerifier:{async verifyBearer(){return{issuer:"https://issuer.example",audience:"zap-pronto",subject:"subject-1"}}}});const request={method:"POST" as const,url:"/v1/inbox/availability",headers:{authorization:"Bearer token","idempotency-key":"availability-offset-1"},payload:{unitId,status:"PAUSED",maxActive:5,pauseReason:"BREAK",pausedUntil:"2030-01-01T12:00:00.123456+02:00",expectedVersion:1}};const success=await app.inject(request);assert.equal(success.statusCode,200);assert.equal(values[0]?.[4],"2030-01-01T10:00:00.123Z");conflict=true;const blocked=await app.inject({...request,headers:{...request.headers,"idempotency-key":"availability-offset-2"}});assert.equal(blocked.statusCode,409);assert.equal(blocked.json().type,"urn:zap-pronto:error:availability-conflict");assert.doesNotMatch(blocked.body,/ACTIVE_WORK|2030-01-01/);await app.close();});

test("availability fails closed and sanitizes forbidden, missing, stale and revoked replay edges",async()=>{const unitId="33333333-3333-4333-8333-333333333333",userId="22222222-2222-4222-8222-222222222222",tenantId="11111111-1111-4111-8111-111111111111";
  for(const scenario of [{name:"forbidden",allowed:false,status:403,error:""},{name:"missing",allowed:true,status:404,error:"AVAILABILITY_NOT_FOUND"},{name:"stale",allowed:true,status:409,error:"AVAILABILITY_CONFLICT"},{name:"revoked replay",allowed:true,status:404,error:"AVAILABILITY_NOT_FOUND"}]as const){let commandCalls=0;const pool:TenantTransactionPool={async connect(){return{async query(sql){if(sql.includes("resolve_oidc_principal"))return{rows:[{tenant_id:tenantId,user_id:userId}]};if(sql.includes("current_actor_has_permission"))return{rows:[{allowed:scenario.allowed}]};if(sql.includes("set_actor_unit_availability")){commandCalls+=1;throw new Error(scenario.error)}return{rows:[]}},release(){}}}};
    const app=await buildApp({pool,identityVerifier:{async verifyBearer(){return{issuer:"https://issuer.example",audience:"zap-pronto",subject:`subject-${scenario.name}`}}}});const response=await app.inject({method:"POST",url:"/v1/inbox/availability",headers:{authorization:"Bearer private-token","idempotency-key":"availability-private-key"},payload:{unitId,status:"AVAILABLE",maxActive:5,expectedVersion:1}});
    assert.equal(response.statusCode,scenario.status,scenario.name);assert.equal(response.headers["cache-control"],"no-store");assert.doesNotMatch(response.body,/private-token|availability-private-key|AVAILABILITY_NOT_FOUND|AVAILABILITY_ACTIVE_WORK_CONFLICT|33333333/i);assert.equal(commandCalls,scenario.allowed?1:0);await app.close();
  }
});

